+// Store Null Pointer
+instruct zStorePNull(memory mem, immP_0 zero, iRegPNoSp tmp1, iRegPNoSp tmp2, rFlagsReg cr)
+%{
+  predicate(UseZGC && !needs_releasing_store(n) && n->as_Store()->barrier_data() != 0);
+  match(Set mem (StoreP mem zero));
+  effect(TEMP tmp1, TEMP tmp2, KILL cr);
+
+  ins_cost(125); // XXX
+  format %{ "sd    $mem, $zero\t# ptr, #@zStorePNull" %}
+  ins_encode %{
+    const Address ref_addr(as_Register($mem$$base), $mem$$disp);
+    z_store_barrier(masm, this, ref_addr, noreg, $tmp1$$Register, $tmp2$$Register, false /* is_atomic */);
+    __ sd($tmp1$$Register, ref_addr);
+  %}
+  ins_pipe(pipe_serial);
+%}
+
