+%{
+  predicate(UseZGC && needs_releasing_store(n) && n->as_Store()->barrier_data() != 0);
+  match(Set mem (StoreP mem zero));
+  effect(TEMP tmp1, TEMP tmp2, KILL cr);
+
+  ins_cost(VOLATILE_REF_COST);
+  format %{ "sd.rl  $mem, $zero\t# ptr, #@zStorePVolatileNull" %}
+  ins_encode %{
+    guarantee($mem$$disp == 0, "impossible encoding");
+    z_store_barrier(masm, this, Address($mem$$Register), noreg, $tmp1$$Register, $tmp2$$Register, false /* is_atomic */);
+    __ sd_rl($tmp1$$Register, $mem$$Register);

